from abc import ABC, abstractmethod


class ProcessorComponent(ABC):
    def __init__(self, mediator=None):
        self._mediator = mediator

    def set_mediator(self, mediator):
        self._mediator = mediator


class FilterComponent(ProcessorComponent):
    def __init__(self, filter_func=None, mediator=None):
        super().__init__(mediator)
        self._filter_func = filter_func

    def set_filter(self, filter_func):
        self._filter_func = filter_func

    def filter(self, items):
        if not self._filter_func:
            return items
        return [item for item in items if self._filter_func(item)]


class TransformComponent(ProcessorComponent):
    def __init__(self, transform_func=None, mediator=None):
        super().__init__(mediator)
        self._transform_func = transform_func

    def set_transform(self, transform_func):
        self._transform_func = transform_func

    def transform(self, items):
        if not self._transform_func:
            return items
        return [self._transform_func(item) for item in items]


class ProcessingMediator:
    def __init__(self):
        self._filter = FilterComponent()
        self._transform = TransformComponent()
        self._filter.set_mediator(self)
        self._transform.set_mediator(self)

    def set_filter(self, filter_func):
        self._filter.set_filter(filter_func)

    def set_transform(self, transform_func):
        self._transform.set_transform(transform_func)

    def process(self, data):
        filtered = self._filter.filter(data)
        transformed = self._transform.transform(filtered)
        return transformed


class DataProcessor:
    def __init__(self, config):
        self._mediator = ProcessingMediator()
        if config.get('filter'):
            self._mediator.set_filter(config['filter'])
        if config.get('transform'):
            self._mediator.set_transform(config['transform'])

    def process(self, data):
