from __future__ import annotations

from abc import ABC, abstractmethod
from typing import Any, Callable


class PipelineComponent(ABC):
    """Base component that holds a reference to the mediator."""

    def __init__(self) -> None:
        self._mediator: ProcessingMediator | None = None

    def set_mediator(self, mediator: ProcessingMediator) -> None:
        self._mediator = mediator


class FilterComponent(PipelineComponent):
    def __init__(
        self, filter_fn: Callable[[Any], bool] | None = None
    ) -> None:
        super().__init__()
        self._filter_fn = filter_fn

    def set_filter(self, filter_fn: Callable[[Any], bool]) -> None:
        self._filter_fn = filter_fn

    def execute(self, items: list[Any]) -> list[Any]:
        if not self._filter_fn:
            return items
        return [item for item in items if self._filter_fn(item)]


class TransformComponent(PipelineComponent):
    def __init__(
        self, transform_fn: Callable[[Any], Any] | None = None
    ) -> None:
        super().__init__()
        self._transform_fn = transform_fn

    def set_transform(self, transform_fn: Callable[[Any], Any]) -> None:
        self._transform_fn = transform_fn

    def execute(self, items: list[Any]) -> list[Any]:
        if not self._transform_fn:
            return items
        return [self._transform_fn(item) for item in items]


class ProcessingMediator:
    """Coordinates filter and transform components in sequence."""

    def __init__(self) -> None:
        self._filter = FilterComponent()
        self._transform = TransformComponent()
        self._filter.set_mediator(self)
        self._transform.set_mediator(self)

    def set_filter(self, filter_fn: Callable[[Any], bool]) -> None:
        self._filter.set_filter(filter_fn)

    def set_transform(self, transform_fn: Callable[[Any], Any]) -> None:
        self._transform.set_transform(transform_fn)

    def process(self, data: list[Any]) -> list[Any]:
        filtered = self._filter.execute(data)
        transformed = self._transform.execute(filtered)
        return transformed


class DataProcessor:
    def __init__(
        self,
        filter_fn: Callable[[Any], bool] | None = None,
        transform_fn: Callable[[Any], Any] | None = None,
    ) -> None:
        self._mediator = ProcessingMediator()
        if filter_fn:
            self._mediator.set_filter(filter_fn)
        if transform_fn:
            self._mediator.set_transform(transform_fn)

    def process(self, data: list[Any]) -> list[Any]:
        return self._mediator.process(data)

